python3 -c "
import json
ps=json.load(open('/opt/trading-bot/positions_regr/positions.json'))
os_=json.load(open('/opt/trading-bot/positions_regr/orders.json'))
om={o['id']:o for o in os_}
for p in ps:
    if p['id']>=238:
        o=om.get(p.get('order_id')) or {}
        print(p['id'],p['sym'],p['side'],p['status'],p.get('reason'),'R%',round(p['R_pct'],3),'net',p.get('net_pct'),'r',p.get('r_mult'),'mfe',p.get('mfe_pct'),'mae',p.get('mae_pct'),'xr',p.get('xr'),'be2',p.get('be2_done'),'parts',len(p.get('parts',[])),'| setup',o.get('setup'),'ctype',(o.get('chan') or {}).get('type'),'cnt',o.get('counter'),'reg',(o.get('regime') or {}).get('regime'),'chase%',round((o['price']/o['atr_c']-1)*100,3),'lag_s',round((o['placed_t']-p['t_in'])/1000),'tin',p['t_in'],'tout',p.get('t_out'))
" | LC_ALL=C tr -cd '\11\12\40-\176'
echo ---SERVICES; systemctl list-units --type=service --state=running --no-pager | grep -E 'chan|pos|acct|tg|class|afd|combo|ob|wall|sez|gen|list|bot' | awk '{print $1}' | tr '\n' ' '
echo; echo ---LOAD; uptime; nproc; ps -eo pcpu,rss,etimes,args --sort=-pcpu | head -8 | cut -c1-140 | LC_ALL=C tr -cd '\11\12\40-\176'
